module ietf-restconf-monitoring {
  namespace "urn:ietf:params:xml:ns:yang:ietf-restconf-monitoring";
  prefix rcmon;

  organization
    "IETF NETCONF (Network Configuration) Working Group";
  contact
    "WG Web:   <https://datatracker.ietf.org/wg/netconf/>
     WG List:  <mailto:netconf@ietf.org>

     Author:   Andy Bierman
               <mailto:andy@yumaworks.com>

     Author:   Martin Bjorklund
               <mailto:mbj@tail-f.com>

     Author:   Kent Watsen
               <mailto:kwatsen@juniper.net>";
  description
    "This module contains monitoring information for the
     RESTCONF protocol.

     Copyright (c) 2017 IETF Trust and the persons identified as
     authors of the code.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Simplified BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (http://trustee.ietf.org/license-info).

     This version of this YANG module is part of RFC 8040; see
     the RFC itself for full legal notices.";

  revision 2017-01-26;

  container restconf-state {
    config false;
    status current;
    description
      "Contains RESTCONF protocol monitoring information.";
    container capabilities {
      config false;
      status current;
      description
        "Contains a list of protocol capability URIs.";
      leaf-list capability {
        type string {
          pattern "[a-z][a-z0-9+.-]*:.*";
        }
        config false;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status current;
        description
          "A RESTCONF protocol capability URI.";
      }
    }
    container streams {
      config false;
      status current;
      description
        "Container representing the notification event streams
         supported by the server.";
      reference
        "RFC 5277, Section 3.4, <streams> element.";
      list stream {
        key "name";
        config false;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status current;
        description
          "Each entry describes an event stream supported by
           the server.";
        leaf name {
          type string;
          config false;
          status current;
          description
            "The stream name.";
          reference
            "RFC 5277, Section 3.4, <name> element.";
        }
        leaf description {
          type string;
          config false;
          status current;
          description
            "Description of stream content.";
          reference
            "RFC 5277, Section 3.4, <description> element.";
        }
        leaf replay-support {
          type boolean;
          default "false";
          config false;
          status current;
          description
            "Indicates if replay buffer is supported for this stream.
             If 'true', then the server MUST support the 'start-time'
             and 'stop-time' query parameters for this stream.";
          reference
            "RFC 5277, Section 3.4, <replaySupport> element.";
        }
        leaf replay-log-creation-time {
          when "../replay-support" {
            description
              "Only present if notification replay is supported.";
          }
          type string {
            pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
          }
          config false;
          status current;
          description
            "Indicates the time the replay log for this stream
             was created.";
          reference
            "RFC 5277, Section 3.4, <replayLogCreationTime>
             element.";
        }
        list access {
          key "encoding";
          config false;
          min-elements 1;
          max-elements 4294967295;
          ordered-by user;
          status current;
          description
            "The server will create an entry in this list for each
             encoding format that is supported for this stream.
             The media type 'text/event-stream' is expected
             for all event streams.  This list identifies the
             subtypes supported for this stream.";
          leaf encoding {
            type string;
            config false;
            status current;
            description
              "This is the secondary encoding format within the
               'text/event-stream' encoding used by all streams.
               The type 'xml' is supported for XML encoding.
               The type 'json' is supported for JSON encoding.";
          }
          leaf location {
            type string {
              pattern "[a-z][a-z0-9+.-]*:.*";
            }
            config false;
            mandatory true;
            status current;
            description
              "Contains a URL that represents the entry point
               for establishing notification delivery via
               server-sent events.";
          }
        }
      }
    }
  }
}
